/**
 * @amc/design-mode: TypeScript twin of the pure logic in
 * `services/langgraph/agency/design/` (Python is the reference). The fixture
 * `tests/fixtures/design-mode.json` is generated by
 * `services/langgraph/tests/test_design_mode_parity_fixture.py`, and so is
 * `src/python-unicode.ts`.
 *
 * Reused, not forked: the catalog data (`packages/shared/style-library/design-styles.json`,
 * passed in by the caller as already-parsed JSON) and the vocabularies from
 * `@amc/shared`'s `styleLibrary.ts` (dimensions, categories, statuses).
 *
 * Left in Python: reading the catalog file and the per-process cache
 * (`load_style_library`, `load_style_registry`), and the FastAPI routes.
 *
 * Where JS and Python differ, and what this twin does:
 * - Pydantic lax mode (`"0.5"`/`True` for a strength, `1`/`"yes"` for a bool)
 *   is refused; the fixture lists these as `lax_divergences`.
 * - `semantic_roles` keys that look like array indices would be reordered by a
 *   JS object (which changes the palette prompt text), so they are refused.
 * - Validation errors carry Design Mode's own `value_error` messages in
 *   Python's order (`ValidationError.valueErrors`); Pydantic's wording for
 *   type/range errors is not reproduced.
 * - Style ids use Python's `\d` (Unicode digits) and `$` (before a final newline).
 */
export { InvalidSelectionError, UnknownStyleError, ValidationError } from './errors';
export {
  STYLE_CATEGORIES,
  STYLE_DIMENSIONS,
  STYLE_ID_PATTERN,
  STYLE_LIBRARY_VERSION,
  getStyle,
  parseStyleLibrary,
  pendingReferences,
  styleCatalogSnapshot,
  type StyleCatalogSnapshot,
  type StyleDefinition,
  type StyleDimension,
  type StyleLibrary,
} from './registry';
export {
  analyzeStyleCompatibility,
  type CompatibilityOptions,
  type CompatibilityReport,
} from './compatibility';
export {
  compileDesignPrompt,
  compileNegativePrompt,
  type DesignBrief,
  type PromptComposition,
  type PromptToken,
} from './prompt';
export {
  COMPOSER_VERSION,
  MAX_SELECTIONS,
  composeStyleSelection,
  compositionId,
  directionFromSelection,
  parseDesignStyleSelection,
  selectionSetError,
  unresolvedDirection,
  type ComposeOptions,
  type ComposedStyle,
  type DesignStyleDirection,
  type DesignStyleSelection,
  type ResolvedStyleToken,
  type StyleSelection,
} from './composer';
export { PYTHON_UNIDATA_VERSION } from './python-unicode';
